  protected void loadNodes(Iterable<ModelNode> modelNodes) {
    for (ModelNode node : modelNodes) {
      this.nodes.add(convertNode(node));
    }
  }

  protected Node convertNode(ModelNode modelNode) {
    Node node = new Node();
    node.id = modelNode.id;
    if (modelNode.translation != null) node.translation.set(modelNode.translation);
    if (modelNode.rotation != null) node.rotation.set(modelNode.rotation);
    if (modelNode.scale != null) node.scale.set(modelNode.scale);
    if (modelNode.parts != null) {
      for (ModelNodePart mnp : modelNode.parts) {
        NodePart np = new NodePart();
        np.meshPart = getMeshPart(mnp.meshPartId);
        np.material = getMaterial(mnp.materialId);
        node.parts.add(np);
      }
    }
    if (modelNode.children != null) {
      for (ModelNode child : modelNode.children) {
        node.addChild(convertNode(child));
      }
    }
    return node;
  }

  protected MeshPart getMeshPart(String id) {
    for (MeshPart part : meshParts) {
      if (part.id.equals(id)) return part;
    }
    throw new GdxRuntimeException("MeshPart not found: " + id);
  }

  protected Material getMaterial(String id) {
    for (Material mat : materials) {
      if (mat.id.equals(id)) return mat;
    }
    throw new GdxRuntimeException("Material not found: " + id);
  }

  protected void loadAnimations(Iterable<ModelAnimation> modelAnimations) {
    for (ModelAnimation anim : modelAnimations) {
      this.animations.add(convertAnimation(anim));
    }
  }

  protected Animation convertAnimation(ModelAnimation anim) {
    Animation result = new Animation();
    result.id = anim.id;
    for (ModelNodeAnimation mna : anim.nodeAnimations) {
      NodeAnimation na = new NodeAnimation();
      na.node = getNode(mna.nodeId);
      for (ModelNodeKeyframe kf : mna.keyframes) {
        NodeKeyframe nk = new NodeKeyframe();
        nk.keytime = kf.keytime;
        if (kf.translation != null) nk.translation.set(kf.translation);
        if (kf.rotation != null) nk.rotation.set(kf.rotation);
        if (kf.scale != null) nk.scale.set(kf.scale);
        na.keyframes.add(nk);
      }
      result.nodeAnimations.add(na);
    }
    return result;
  }

  protected Node getNode(String id) {
    for (Node node : nodes) {
      if (node.id.equals(id)) return node;
    }
    throw new GdxRuntimeException("Node not found: " + id);
  }

  public void calculateTransforms() {
    for (Node node : nodes) {
      node.calculateTransforms(true);
    }
  }

